        var fails = 0;
        try { fails = parseInt(sessionStorage.getItem(D.SPA_FAIL_KEY), 10) || 0; } catch (e) { /* no storage */ }
        if (fails >= D.SPA_FAIL_MAX) { location.assign(path); return; }
